      "Alle Dschinns: Grad 1: Schutz vor Gut und Böse | Grad 2: Macht der Vorstellungskraft | Grad 3: Nahrung und Wasser erschaffen | Grad 4: Tödliches Phantom | Grad 5: Erschaffung | Grad 9: Wunsch.",
