      "Als Bonusaktion in deinem Zug kannst du Trefferpunkte in Höhe von 1W10 + deiner Kämpferstufe wiederherstellen. Nach einmaligem Einsatz steht die Fähigkeit erst nach einer kurzen oder langen Rast wieder zur Verfügung."
